def cargar_roles(apps, schema_editor):
    """Los roles con que viene el sistema, con los permisos que tenían cuando
    eran fijos (ver retiros/roles.py). Los permisos de Django se crean al
    final de migrate: aquí se crean antes para poder asignarlos."""
    from django.contrib.auth.management import create_permissions

    from retiros.models import RolSistema
    from retiros.roles import ROLES_SISTEMA, permisos_iniciales

    for config in apps.get_app_configs():
        config.models_module = True
        create_permissions(config, verbosity=0, apps=apps)
        config.models_module = None
    Rol = apps.get_model("retiros", "Rol")
    Permission = apps.get_model("auth", "Permission")
    de_la_app = {p.codename: p for p in Permission.objects.filter(content_type__app_label="retiros")}
    for codigo, (ambito, sensibles, _permisos, descripcion) in ROLES_SISTEMA.items():
        rol, _ = Rol.objects.update_or_create(codigo=codigo, defaults={
            "nombre": RolSistema(codigo).label, "ambito": ambito,
            "ve_datos_sensibles": sensibles, "descripcion": descripcion, "sistema": True,
        })
        rol.permisos.set([de_la_app[c] for c in permisos_iniciales(codigo, de_la_app)
                          if c in de_la_app])


def pasar_codigos(apps, schema_editor):
    """Cada asignación, del código del rol ("logistica") a su fila de Rol."""
    Rol = apps.get_model("retiros", "Rol")
    AsignacionRol = apps.get_model("retiros", "AsignacionRol")
    roles = {r.codigo: r for r in Rol.objects.all()}
    for a in AsignacionRol.objects.all():
        a.rol = roles[a.rol_codigo]
        a.save(update_fields=["rol"])


